import itertools

def get_all_points():
    points = []
    for x in range(10):
        for y in range(10):
            for z in range(10):
                points.append((x+y, y+z, z+x))
    return points

def dist(p1, p2):
    return abs(p1[0]-p2[0]) + abs(p1[1]-p2[1]) + abs(p1[2]-p2[2])

def is_injective(points, queries):
    seen = {}
    for p in points:
        res = tuple(dist(p, q) for q in queries)
        if res in seen:
            return False, (p, seen[res])
        seen[res] = p
    return True, None

def solve():
    points = get_all_points()

    # Try k=2
    # Since there are 1000*999/2 pairs, we can try a random search or just check some.
    # A random search might be faster.
    import random

    for attempt in range(100000):
        q1 = random.choice(points)
        q2 = random.choice(points)
        inj, fail = is_injective(points, [q1, q2])
        if inj:
            return 2, (q1, q2)

    # If k=2 fails for 100,000 random pairs, maybe it's 3.
    # Let's check k=3 similarly.
    for attempt in range(100000):
        q1 = random.choice(points)
        q2 = random.choice(points)
        q3 = random.choice(points)
        inj, fail = is_injective(points, [q1, q2, q3])
        if inj:
            return 3, (q1, q2, q3)

    return None, None

res_k, res_queries = solve()
print(f"Result: {res_k}, Queries: {res_queries}")

