def check_k2():
    points = get_all_points()

    # Try every possible q1
    for q1 in points:
        # Partition points by distance to q1
        partitions = {}
        for p in points:
            d = dist(p, q1)
            if d not in partitions:
                partitions[d] = []
            partitions[d].append(p)

        # For this q1, we need to find q2 that distinguishes all points in each partition
        # This means for each partition, the distances to q2 must be distinct.
        # This is a much smaller condition to check for each q2.

        # Let's try some q2s
        # To speed up, we can't try all 1000 q2s for every q1 (10^6 total).
        # Actually 10^6 is not that many!
        for q2 in points:
            possible = True
            for d in partitions:
                s_d = partitions[d]
                if len(s_d) <= 1:
                    continue

                # Check if dist(p, q2) is injective on s_d
                dists_to_q2 = set()
                for p in s_d:
                    d2 = dist(p, q2)
                    if d2 in dists_to_q2:
                        possible = False
                        break
                    dists_to_q2.add(d2)
                if not possible:
                    break
            if possible:
                return True, (q1, q2)
    return False, None

res_k2, queries_k2 = check_k2()
