import itertools

def get_all_points(n):
    points = []
    for x in range(n):
        for y in range(n):
            for z in range(n):
                points.append((x+y, y+z, z+x))
    return points

def dist(p1, p2):
    return abs(p1[0]-p2[0]) + abs(p1[1]-p2[1]) + abs(p1[2]-p2[2])

def is_injective(points, queries):
    seen = {}
    for p in points:
        res = tuple(dist(p, q) for q in queries)
        if res in seen:
            return False, (p, seen[res])
        seen[res] = p
    return True, None

def solve_for_n(n):
    points = get_all_points(n)
    # Try k=1
    for q in points:
        if is_injective(points, [q])[0]:
            return 1
    # Try k=2
    for q1, q2 in itertools.combinations(points, 2):
        if is_injective(points, [q1, q2])[0]:
            return 2
    # Try k=3
    for q1, q2, q3 in itertools.combinations(points, 3):
        if is_injective(points, [q1, q2, q3])[0]:
            return 3
    return 4

